import json

with open('/tmp/registry_parsed.json', 'r') as f:
    exps = json.load(f)

# Search for "4/31", "4/28", "0.827", "0.0556", "1300-step", "1,300-step"
# in ALL fields of ALL experiments
search_terms = ['4/31', '4/28', '0.827', '0.0556', '1300-step', '1,300-step', '1300 step', '1,300 step', 'AUROC']

for term in search_terms:
    print(f"\n{'='*60}")
    print(f"SEARCH: '{term}'")
    print(f"{'='*60}")
    found = False
    for eid, edata in exps.items():
        full_str = json.dumps(edata)
        if term in full_str:
            found = True
            print(f"  >> {eid}")
            # Show which field contains it
            for key in ['metrics', 'conclusion', 'notes', 'extra', 'hypothesis']:
                if key in edata:
                    val_str = str(edata[key])
                    if term in val_str:
                        # Print a snippet around the term
                        idx = val_str.find(term)
                        start = max(0, idx - 80)
                        end = min(len(val_str), idx + len(term) + 80)
                        print(f"     [{key}]: ...{val_str[start:end]}...")
    if not found:
        print("  (not found)")

# Also search for aggregate/count references
print(f"\n{'='*60}")
print(f"SEARCH: 'aggregate' or 'count' in notes/conclusion")
print(f"{'='*60}")
for eid, edata in exps.items():
    for key in ['notes', 'conclusion', 'extra']:
        if key in edata:
            val_str = str(edata[key]).lower()
            if 'aggregate' in val_str or 'act count' in val_str:
                print(f"  >> {eid} [{key}]: {str(edata[key])[:200]}")
